 draft=clone(library.waves[0]||draft);renderEditor();renderPlaylist();renderVortex();
 return {runner,restart(){const data=validateLibrary(library,types);if(sequenceMode==='playlist'&&!data.playlist.length)throw Error('Ajoute une vague à la playlist');runner.stop();sim.cfg.vortexRadius=data.vortex.startRadius;sim.reset();if(sequenceMode==='playlist')runner.start(data);else if(sequenceMode==='vortex')runner.startVortex(data);return sequenceMode;},setVortexDefaults(v){library.vortex.rate=v.rate;library.vortex.startRadius=v.startRadius;renderVortex();},update(){runner.tick();housePopStatus.textContent=sim.cfg.buildingPopInterval<=0?'Pop maison arrêté.':sim.freeBuildingSlot()===undefined?'Aucun emplacement libre (12 / 12).':'Prochaine maison dans '+Math.ceil(Math.max(0,sim.cfg.buildingPopInterval-sim.buildingPopElapsed))+' s · '+(12-sim.buildings.length)+' emplacements libres.';const plan=runner.vortexPlan,next=plan?.triggers.find(t=>t.state==='waiting');status.textContent=runner.state+' · '+runner.jobs.length+' monstres à apparaître'+(plan?' · rayon '+sim.cfg.vortexRadius.toFixed(2)+' · '+(next?'prochain seuil '+next.radius.toFixed(2)+' : '+next.wave.name:'aucun seuil restant'):'');for(const host of [radiusRow,document.querySelector('#worldFields label')])host?.querySelectorAll('input').forEach(input=>{if(document.activeElement!==input)input.value=+sim.cfg.vortexRadius.toFixed(2);});},refreshProfile:profileUi,getLibrary:()=>clone(library)};
